34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
40	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
41	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
42	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
43	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
70	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        rejectMissingOrBlankFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        owner.setAddress(normalizeAddress(owner.getAddress()));
125	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
126	        owner.setEmail(normalizeEmail(owner.getEmail()));
127	        if (owner.getRegistrationDate() == null) {
128	            owner.setRegistrationDate(LocalDate.now());
129	        }
130	        rejectDuplicateTelephone(owner.getTelephone());
131	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
132	            assignHousehold(owner);
133	        } else {
134	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
135	        }
136	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
137	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
138	        this.clinicService.saveOwner(owner);
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        headers.setLocation(UriComponentsBuilder.newInstance()
141	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
142	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
157	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        this.clinicService.deleteOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
198	            Pet currentPet = this.clinicService.findPetById(petId);
199	            if (currentPet != null) {
200	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
201	                currentPet.setName(petFieldsDto.getName());
202	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
203	                this.clinicService.savePet(currentPet);
204	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
213	        HttpHeaders headers = new HttpHeaders();
214	        Visit visit = visitMapper.toVisit(visitFieldsDto);
215	        Pet pet = new Pet();
216	        pet.setId(petId);
217	        visit.setPet(pet);
218	        this.clinicService.saveVisit(visit);
219	        VisitDto visitDto = visitMapper.toVisitDto(visit);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
221	            .buildAndExpand(visit.getId()).toUri());
222	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
223	    }
224	
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner != null) {
231	            Pet pet = owner.getPet(petId);
232	            if (pet != null) {
233	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    /**
240	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
241	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
242	     *
243	     * @param fields the submitted owner fields
244	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
245	     *                                        {@code null} or blank, or if address is blank after
246	     *                                        normalization
247	     */
248	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
249	        List<String> missing = new ArrayList<>();
250	        if (isBlank(fields.getFirstName())) {
251	            missing.add("firstName");
252	        }
253	        if (isBlank(fields.getLastName())) {
254	            missing.add("lastName");
255	        }
256	        if (isBlank(normalizeAddress(fields.getAddress()))) {
257	            missing.add("address");
258	        }
259	        if (isBlank(fields.getCity())) {
260	            missing.add("city");
261	        }
262	        if (isBlank(fields.getTelephone())) {
263	            missing.add("telephone");
264	        }
265	        if (!missing.isEmpty()) {
266	            throw new RequiredFieldsMissingException(missing);
267	        }
268	    }
269	
270	    private boolean isBlank(String value) {
271	        return value == null || value.isBlank();
272	    }
273	
274	    /**
275	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
276	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
277	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
278	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
279	     *
280	     * @param telephone the raw telephone value from the request
281	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
282	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
283	     */
284	    private String normalizeTelephone(String telephone) {
285	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
286	        String digits;
287	        if (cleaned.startsWith("+")) {
288	            digits = cleaned.substring(1);
289	        } else {
290	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
291	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
292	            digits = "61" + national;
293	        }
294	        if (!digits.matches("[0-9]{8,15}")) {
295	            throw new InvalidTelephoneException(cleaned);
296	        }
297	        return "+" + digits;
298	    }
299	
300	    /**
301	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
302	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
303	     * lower-cased.
304	     *
305	     * @param email the raw email value from the request, or {@code null} if omitted
306	     * @return the lower-cased email, or {@code null} if none was supplied
307	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
308	     */
309	    private String normalizeEmail(String email) {
310	        if (email == null) {
311	            return null;
312	        }
313	        String trimmed = email.strip();
314	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
315	            throw new InvalidEmailException(email);
316	        }
317	        return trimmed.toLowerCase(Locale.ROOT);
318	    }
319	
320	    /**
321	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
322	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
323	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
324	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
325	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
326	     *
327	     * @param address the raw address value from the request (may be {@code null})
328	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
329	     */
330	    private String normalizeAddress(String address) {
331	        if (address == null) {
332	            return "";
333	        }
334	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
335	        if (collapsed.isEmpty()) {
336	            return "";
337	        }
338	        String[] tokens = collapsed.split(" ");
339	        StringBuilder sb = new StringBuilder(collapsed.length());
340	        for (int i = 0; i < tokens.length; i++) {
341	            if (i > 0) {
342	                sb.append(' ');
343	            }
344	            sb.append(expandAddressAbbreviation(tokens[i]));
345	        }
346	        return sb.toString();
347	    }
348	
349	    /**
350	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
351	     * returns the token unchanged when it is not a recognised abbreviation.
352	     *
353	     * @param token an upper-cased whole-word address token
354	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
355	     */
356	    private String expandAddressAbbreviation(String token) {
357	        return switch (token) {
358	            case "ST" -> "STREET";
359	            case "RD" -> "ROAD";
360	            case "AVE" -> "AVENUE";
361	            default -> token;
362	        };
363	    }
364	
365	    /**
366	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
367	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
368	     *
369	     * @param telephone the normalized (E.164) telephone of the owner being created
370	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
371	     */
372	    /**
373	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
374	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
375	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
376	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
377	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
378	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
379	     *
380	     * @param city the owner's city
381	     * @param lastName the owner's last name
382	     * @return the assigned customer code
383	     */
384	    private String generateCustomerCode(String city, String lastName) {
385	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
386	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
387	        int sequence = (int) this.clinicService.findAllOwners().stream()
388	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
389	            .count() + 1;
390	        return String.format("%s-%s-%04d", city3, last3, sequence);
391	    }
392	
393	    /**
394	     * Counts how many existing owners already share the given first name and last name, compared
395	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
396	     * owner being created.
397	     *
398	     * @param firstName the first name of the owner being created
399	     * @param lastName the last name of the owner being created
400	     * @return the number of existing owners with the same first and last name (case-insensitively)
401	     */
402	    private int countNamesakes(String firstName, String lastName) {
403	        return (int) this.clinicService.findAllOwners().stream()
404	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
405	                && lastName.equalsIgnoreCase(existing.getLastName()))
406	            .count();
407	    }
408	
409	    private void rejectDuplicateTelephone(String telephone) {
410	        boolean taken = this.clinicService.findAllOwners().stream()
411	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
412	        if (taken) {
413	            throw new DuplicateTelephoneException(telephone);
414	        }
415	    }
416	
417	    /**
418	     * Rejects a create request whose owner shares both last name and address with an existing owner.
419	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
420	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
421	     * differing case) still count as the same household.
422	     *
423	     * @param lastName the last name of the owner being created
424	     * @param address the address of the owner being created
425	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
426	     */
427	    private void rejectDuplicateHousehold(String lastName, String address) {
428	        String normalizedLastName = normalizeForComparison(lastName);
429	        String normalizedAddress = normalizeForComparison(address);
430	        boolean taken = this.clinicService.findAllOwners().stream()
431	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
432	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
433	        if (taken) {
434	            throw new DuplicateHouseholdException(lastName, address);
435	        }
436	    }
437	
438	    /**
439	     * Assigns the owner being created into a shared household. When at least one existing owner has the
440	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
441	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
442	     * reused when present; otherwise a deterministic id derived from the household's last name and address
443	     * is minted, so independently created members of the same household converge on one value. When no
444	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
445	     *
446	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
447	     */
448	    private void assignHousehold(Owner owner) {
449	        String normalizedLastName = normalizeForComparison(owner.getLastName());
450	        String normalizedAddress = normalizeForComparison(owner.getAddress());
451	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
452	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
453	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
454	            .toList();
455	        if (housemates.isEmpty()) {
456	            return;
457	        }
458	        String householdId = housemates.stream()
459	            .map(Owner::getHouseholdId)
460	            .filter(id -> id != null && !id.isBlank())
461	            .findFirst()
462	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
463	        owner.setHouseholdId(householdId);
464	        for (Owner housemate : housemates) {
465	            if (!householdId.equals(housemate.getHouseholdId())) {
466	                housemate.setHouseholdId(householdId);
467	                this.clinicService.saveOwner(housemate);
468	            }
469	        }
470	    }
471	
472	    /**
473	     * Derives a stable household identifier from the normalized last name and address of a household, as
474	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
475	     * deterministic, so any owner independently joining the same household computes the same identifier.
476	     *
477	     * @param normalizedLastName the household's last name, already normalized for comparison
478	     * @param normalizedAddress the household's address, already normalized for comparison
479	     * @return a stable, shareable household identifier
480	     */
481	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
482	        String key = normalizedLastName + "|" + normalizedAddress;
483	        try {
484	            byte[] digest = MessageDigest.getInstance("SHA-256")
485	                .digest(key.getBytes(StandardCharsets.UTF_8));
486	            StringBuilder sb = new StringBuilder(digest.length * 2);
487	            for (byte b : digest) {
488	                sb.append(String.format("%02x", b));
489	            }
490	            return sb.substring(0, 16);
491	        } catch (NoSuchAlgorithmException e) {
492	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
493	        }
494	    }
495	
496	    /**
497	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
498	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
499	     * lower-cased.
500	     *
501	     * @param value the raw value to normalize (may be {@code null})
502	     * @return the normalized value, or an empty string when {@code value} is {@code null}
503	     */
504	    private String normalizeForComparison(String value) {
505	        if (value == null) {
506	            return "";
507	        }
